fields.CSS:
#hrv-mushroom-doorway {
  width: 100%;
}

#hrv-mushroom-doorway .hrv-mushroom-outage[hidden],
#hrv-mushroom-doorway .hrv-mushroom-retry[hidden],
#hrv-mushroom-doorway > #hrv-mushroom-exploration-root[hidden] {
  display: none !important;
}

#hrv-mushroom-doorway .hrv-mushroom-outage {
  box-sizing: border-box;
  display: grid;
  width: min(680px, calc(100% - 28px));
  min-height: 410px;
  margin: 42px auto;
  padding: clamp(24px, 5vw, 44px);
  justify-items: center;
  overflow-wrap: anywhere;
  border: 1px solid rgba(221, 191, 121, 0.45);
  border-radius: 28px;
  color: #fff1cf;
  background:
    radial-gradient(circle at 20% 10%, rgba(151, 182, 100, 0.2), transparent 280px),
    linear-gradient(145deg, #183b31, #092f29);
  box-shadow: 0 20px 50px rgba(9, 35, 29, 0.25);
  font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  text-align: center;
}

#hrv-mushroom-doorway .hrv-mushroom-outage__scene {
  position: relative;
  display: grid;
  width: min(210px, 100%);
  aspect-ratio: 1;
  place-items: center;
}

#hrv-mushroom-doorway .hrv-mushroom-outage__guide {
  font-size: clamp(80px, 22vw, 128px);
  line-height: 1;
  filter: drop-shadow(0 14px 18px rgba(0, 0, 0, 0.22));
}

#hrv-mushroom-doorway .hrv-mushroom-outage__question,
#hrv-mushroom-doorway .hrv-mushroom-outage__map {
  position: absolute;
  display: grid;
  place-items: center;
  border: 1px solid rgba(255, 241, 207, 0.45);
  box-shadow: 0 8px 18px rgba(0, 0, 0, 0.2);
}

#hrv-mushroom-doorway .hrv-mushroom-outage__question {
  top: 10%;
  right: 3%;
  width: 44px;
  height: 44px;
  border-radius: 50%;
  color: #183b31;
  background: #e8c481;
  font-size: 26px;
  font-weight: 800;
}

#hrv-mushroom-doorway .hrv-mushroom-outage__map {
  right: 3%;
  bottom: 14%;
  width: 44px;
  height: 38px;
  border-radius: 10px;
  background: #183b31;
  font-size: 24px;
  transform: rotate(8deg);
}

#hrv-mushroom-doorway .hrv-mushroom-outage__eyebrow {
  margin: 0 0 10px;
  color: #e8c481;
  font-size: 12px;
  font-weight: 750;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

#hrv-mushroom-doorway .hrv-mushroom-outage__title {
  margin: 0;
  color: #fff1cf;
  font-family: Georgia, "Times New Roman", serif;
  font-size: clamp(27px, 5vw, 42px);
  line-height: 1.15;
}

#hrv-mushroom-doorway .hrv-mushroom-outage__copy {
  max-width: 480px;
  margin: 16px 0 0;
  color: #e1ead6;
  font-size: 16px;
  line-height: 1.65;
}

#hrv-mushroom-doorway .hrv-mushroom-retry {
  min-height: 48px;
  margin-top: 20px;
  padding: 10px 24px;
  border: 1px solid #e8c481;
  border-radius: 8px;
  color: #183b31;
  background: #e8c481;
  font: 700 16px/1.4 system-ui, sans-serif;
  cursor: pointer;
}

#hrv-mushroom-doorway .hrv-mushroom-retry:focus-visible {
  outline: 3px solid #fff1cf;
  outline-offset: 4px;
}

@media (max-width: 480px) {
  #hrv-mushroom-doorway .hrv-mushroom-outage {
    width: 100%;
    min-height: 0;
    margin: 24px auto;
    padding: 20px 14px;
    border-radius: 20px;
  }

  #hrv-mushroom-doorway .hrv-mushroom-outage__scene {
    width: min(160px, 100%);
  }

  #hrv-mushroom-doorway .hrv-mushroom-outage__title {
    font-size: clamp(23px, 7vw, 30px);
  }
}

